window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-51074f550425904c"]={"versions": [{"id": "FIG-51074f550425904c", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (ECU Configuration Parameter Definition Metamodell / BSWMD-Struktur).</li>\n<li><strong>Architektur-Kontext:</strong> MCAL (Microcontroller Abstraction Layer), I/O-Treiberbereich nach AUTOSAR Classic Platform (SWS PortDriver, R22-11).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Top-Level-Struktur der Port-Treiber-Konfiguration (<code>Port.arxml</code>). Das Diagramm trennt statische Vorübersetzungs-Parameter (<code>PortGeneral</code>) von den hardware- und pin-spezifischen Initialisierungsdaten (<code>PortConfigSet</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Port: EcucModuleDef</code>:</strong></li>\n<li>Metaklasse zur Repräsentation der Moduldefinition des MCAL-Port-Treibers im BSW-Modul-Metamodell.</li>\n<li><em>Multiplizität:</em> <code>0..1</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Ein System kann den Port-Treiber enthalten oder weglassen, pro ECU-Konfiguration existiert maximal eine Instanz.</li>\n<li><strong><code>PortGeneral: EcucParamConfContainerDef</code> (SWS-ID: <code>ECUC_Port_00122</code>):</strong></li>\n<li>Container für allgemeine, modulweite Konfigurationsparameter (z. B. Aktivierung des Development Error Detection <code>PortDevErrorDetect</code>, Aktivierung von APIs wie <code>PortSetPinDirectionApi</code>, <code>PortSetPinModeApi</code>, <code>PortVersionInfoApi</code>).</li>\n<li><em>Beziehung:</em> Strikte Komposition (<code>+container</code>) ausgehend von <code>Port</code>.</li>\n<li><em>Multiplizität:</em> Exakt <code>1</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code> – obligatorisch vorhanden).</li>\n<li><strong><code>PortConfigSet: EcucParamConfContainerDef</code> (SWS-ID: <code>ECUC_Port_00124</code>):</strong></li>\n<li>Multi-Konfigurations-Container für Hardware-abhängige Pin- und Port-Initialisierungsstrukturen (Sub-Container für Ports, Pins, Richtungen, Multiplexing/Modi, Pull-Up/Down-Widerstände).</li>\n<li><em>Beziehung:</em> Strikte Komposition (<code>+container</code>) ausgehend von <code>Port</code>.</li>\n<li><em>Multiplizität:</em> Mindestens <code>1</code> (enthält die Post-Build- bzw. Link-Time-Konfigurationssätze).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm bildet keine Laufzeit- oder Call-Sequenzen ab, sondern die Schema-Hierarchie für den AUTOSAR-Konfigurations- und Codegenerierungs-Workflow.</li>\n<li><strong>Laufzeitbezug zur Initialisierung:</strong></li>\n<li>Die in <code>PortConfigSet</code> definierten Parameter werden vom Codegenerator in typisierte C-Datenstrukturen (<code>Port_ConfigType</code>) übersetzt.</li>\n<li>Diese Datenstruktur wird der Initialisierungsfunktion <code>Port_Init(const Port_ConfigType* ConfigPtr)</code> zur Laufzeit beim System-Startup (üblicherweise via <code>EcuM</code>/<code>BswM</code>) übergeben, um die Pin-Multiplexer und Register vor allen anderen Peripherietreibern (DIO, SPI, CAN, PWM) zu konfigurieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations-Klassen & Bindungszeitpunkte:</strong></li>\n<li><strong><code>PortGeneral</code>:</strong> Enthält rein <code>Pre-Compile</code>-Parameter (statische <code>#define</code>-Schalter im generierten <code>Port_Cfg.h</code>).</li>\n<li><strong><code>PortConfigSet</code>:</strong> Ermöglicht je nach Implementierungs- und Systemanspruch <code>Post-Build-Selectable</code>- oder <code>Post-Build-Loadable</code>-Konfigurationen für unterschiedliche ECU-Varianten bzw. Hardware-Revisionen.</li>\n<li><strong>Einschränkungen für MCAL-/BSW-Entwickler:</strong></li>\n<li>Da <code>PortGeneral</code> zwingend die Kardinalität <code>1..1</code> aufweist, muss jeder Port-Treiber-Stack zwingend die globalen Modulschalter bereitstellen.</li>\n<li>Änderungen an Pins zur Laufzeit (z. B. Richtungswechsel oder Modus-Umschaltung) sind nur dann als API verfügbar (<code>Port_SetPinDirection</code>, <code>Port_SetPinMode</code>), wenn die entsprechenden Flags in <code>PortGeneral</code> auf <code>TRUE</code> stehen und der jeweilige Pin in <code>PortConfigSet</code> als änderbar (<code>PortPinDirectionChangeable = TRUE</code>, <code>PortPinModeChangeable = TRUE</code>) deklariert ist.</li>\n</ul>"}, {"id": "FIG-e885f6bf9b3ebdf9", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Kombination aus AUTOSAR-Parameter-Definitionstabelle (ECUC-Spezifikation) und UML-Klassendiagramm (BSWMD-Metamodell).</li>\n<li><strong>Architektur-Kontext:</strong> MCAL (Microcontroller Abstraction Layer), I/O-Treiberbereich nach AUTOSAR Classic Platform (SWS PortDriver, R23-11).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Moduleigenschaften (<code>[ECUC_Port_00135]</code>) und der Top-Level-Konfigurationshierarchie des Port-Treibers (<code>Port.arxml</code>). Definiert Konfigurationsvarianten und trennt globale Parameter (<code>PortGeneral</code>) von pin-spezifischen Initialisierungsdaten (<code>PortConfigSet</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Modulspezifikation <code>[ECUC_Port_00135]</code> (<code>Port</code>):</strong></li>\n<li><em>Module Name:</em> <code>Port</code></li>\n<li><em>Description:</em> <code>Configuration of the Port module.</code></li>\n<li><em>Post-Build Variant Support:</em> <code>true</code></li>\n<li><em>Supported Config Variants:</em> <code>VARIANT-POST-BUILD</code>, <code>VARIANT-PRE-COMPILE</code></li>\n<li><em>Included Containers:</em></li>\n<li><code>PortConfigSet</code>: Multiplizität <code>1</code>, Scope/Dependency: Enthält Konfigurationsparameter und Sub-Container des AUTOSAR-Port-Moduls.</li>\n<li><code>PortGeneral</code>: Multiplizität <code>1</code>, Scope/Dependency: Modulweite Konfigurationsparameter des Port-Treibers.</li>\n<li><strong><code>Port: EcucModuleDef</code>:</strong></li>\n<li>Metaklasse zur Repräsentation der Moduldefinition des MCAL-Port-Treibers.</li>\n<li><em>Multiplizität:</em> <code>0..1</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><strong><code>PortGeneral: EcucParamConfContainerDef</code>:</strong></li>\n<li>Container für allgemeine, modulweite Konfigurationsparameter (z. B. Development Error Detection, globale API-Aktivierungsflags).</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>) ausgehend von <code>Port</code>.</li>\n<li><em>Multiplizität:</em> Exakt <code>1</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><strong><code>PortConfigSet: EcucParamConfContainerDef</code>:</strong></li>\n<li>Container für Hardware-abhängige Pin- und Port-Initialisierungsstrukturen (Pins, Richtungen, Modi, Multiplexing).</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>) ausgehend von <code>Port</code>.</li>\n<li><em>Multiplizität:</em> <code>1</code> gemäß Spezifikationstabelle.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm bildet keine Laufzeit- oder Call-Sequenzen ab, sondern die Schema-Hierarchie für den AUTOSAR-Konfigurations- und Codegenerierungs-Workflow.</li>\n<li><strong>Laufzeitbezug zur Initialisierung:</strong></li>\n<li>Die in <code>PortConfigSet</code> definierten Parameter werden vom Codegenerator in typisierte C-Datenstrukturen (<code>Port_ConfigType</code>) übersetzt.</li>\n<li>Diese Datenstruktur wird der Initialisierungsfunktion <code>Port_Init(const Port_ConfigType* ConfigPtr)</code> zur Laufzeit beim System-Startup (üblicherweise via <code>EcuM</code>/<code>BswM</code>) übergeben, um die Pin-Multiplexer und Register vor allen anderen Peripherietreibern (DIO, SPI, CAN, PWM) zu konfigurieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations-Klassen & Bindungszeitpunkte:</strong></li>\n<li><strong>Unterstützte Varianten:</strong> Das Modul unterstützt explizit <code>VARIANT-POST-BUILD</code> und <code>VARIANT-PRE-COMPILE</code> (<code>Post-Build Variant Support: true</code>).</li>\n<li><strong><code>PortGeneral</code>:</strong> Enthält Vorübersetzungs-Parameter (<code>Pre-Compile</code>), die statische Schalter im generierten Treiber definieren.</li>\n<li><strong><code>PortConfigSet</code>:</strong> Dient der Konfiguration hardware-abhängiger Pin-Initialisierungsdaten, die je nach gewählter Variante als Pre-Compile oder Post-Build realisiert werden können.</li>\n<li><strong>Einschränkungen für MCAL-/BSW-Entwickler:</strong></li>\n<li>Beide Container (<code>PortGeneral</code> und <code>PortConfigSet</code>) besitzen die Multiplizität <code>1</code> und sind obligatorischer Bestandteil der Modulkonfiguration.</li>\n<li>Modulweite Schalter in <code>PortGeneral</code> steuern das Vorhandensein optionaler APIs (z. B. <code>Port_SetPinDirection</code>, <code>Port_SetPinMode</code>), welche auf den in <code>PortConfigSet</code> parametrierten Pins operieren.</li>\n</ul>"}, {"id": "FIG-30b742e6a471671b", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (ECU Configuration Parameter Definition Metamodell / BSWMD-Struktur).</li>\n<li><strong>Architektur-Kontext:</strong> MCAL (Microcontroller Abstraction Layer), I/O-Treiberbereich nach AUTOSAR Classic Platform (SWS PortDriver, R24-11).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Top-Level-Struktur der Port-Treiber-Konfiguration (<code>Port.arxml</code>). Das Diagramm trennt statische Vorübersetzungs-Parameter (<code>PortGeneral</code>) von den hardware- und pin-spezifischen Initialisierungsdaten (<code>PortConfigSet</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Port: EcucModuleDef</code>:</strong></li>\n<li>Metaklasse zur Repräsentation der Moduldefinition des MCAL-Port-Treibers im BSW-Modul-Metamodell.</li>\n<li><em>Multiplizität:</em> <code>0..1</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Ein System kann den Port-Treiber enthalten oder weglassen, pro ECU-Konfiguration existiert maximal eine Instanz.</li>\n<li><strong><code>PortGeneral: EcucParamConfContainerDef</code>:</strong></li>\n<li>Container für allgemeine, modulweite Konfigurationsparameter (z. B. Aktivierung des Development Error Detection <code>PortDevErrorDetect</code>, Aktivierung von APIs wie <code>PortSetPinDirectionApi</code>, <code>PortSetPinModeApi</code>, <code>PortVersionInfoApi</code>).</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>) ausgehend von <code>Port</code>.</li>\n<li><em>Multiplizität:</em> Exakt <code>1</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><strong><code>PortConfigSet: EcucParamConfContainerDef</code>:</strong></li>\n<li>Multi-Konfigurations-Container für Hardware-abhängige Pin- und Port-Initialisierungsstrukturen (Sub-Container für Ports, Pins, Richtungen, Multiplexing/Modi, Pull-Up/Down-Widerstände).</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>) ausgehend von <code>Port</code>.</li>\n<li><em>Multiplizität:</em> Mindestens <code>1</code> (enthält die Post-Build- bzw. Link-Time-Konfigurationssätze).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm bildet keine Laufzeit- oder Call-Sequenzen ab, sondern die Schema-Hierarchie für den AUTOSAR-Konfigurations- und Codegenerierungs-Workflow.</li>\n<li><strong>Laufzeitbezug zur Initialisierung:</strong></li>\n<li>Die in <code>PortConfigSet</code> definierten Parameter werden vom Codegenerator in typisierte C-Datenstrukturen (<code>Port_ConfigType</code>) übersetzt.</li>\n<li>Diese Datenstruktur wird der Initialisierungsfunktion <code>Port_Init(const Port_ConfigType* ConfigPtr)</code> zur Laufzeit beim System-Startup (üblicherweise via <code>EcuM</code>/<code>BswM</code>) übergeben, um die Pin-Multiplexer und Register vor allen anderen Peripherietreibern (DIO, SPI, CAN, PWM) zu konfigurieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations-Klassen & Bindungszeitpunkte:</strong></li>\n<li><strong><code>PortGeneral</code>:</strong> Enthält rein <code>Pre-Compile</code>-Parameter (statische <code>#define</code>-Schalter im generierten <code>Port_Cfg.h</code>).</li>\n<li><strong><code>PortConfigSet</code>:</strong> Ermöglicht je nach Implementierungs- und Systemanspruch <code>Post-Build-Selectable</code>- oder <code>Post-Build-Loadable</code>-Konfigurationen für unterschiedliche ECU-Varianten bzw. Hardware-Revisionen.</li>\n<li><strong>Einschränkungen für MCAL-/BSW-Entwickler:</strong></li>\n<li>Da <code>PortGeneral</code> zwingend die Kardinalität <code>1..1</code> aufweist, muss jeder Port-Treiber-Stack zwingend die globalen Modulschalter bereitstellen.</li>\n<li>Änderungen an Pins zur Laufzeit (z. B. Richtungswechsel oder Modus-Umschaltung) sind nur dann als API verfügbar (<code>Port_SetPinDirection</code>, <code>Port_SetPinMode</code>), wenn die entsprechenden Flags in <code>PortGeneral</code> auf <code>TRUE</code> stehen und der jeweilige Pin in <code>PortConfigSet</code> dafür freigegeben ist.</li>\n</ul>"}, {"id": "FIG-4ae9b051730aea79", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (ECU Configuration Parameter Definition Metamodell / BSWMD-Struktur).</li>\n<li><strong>Architektur-Kontext:</strong> MCAL (Microcontroller Abstraction Layer), I/O-Treiberbereich nach AUTOSAR Classic Platform (SWS PortDriver, R24-11).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Top-Level-Struktur der Port-Treiber-Konfiguration (<code>Port.arxml</code>). Das Diagramm trennt statische Vorübersetzungs-Parameter (<code>PortGeneral</code>) von den hardware- und pin-spezifischen Initialisierungsdaten (<code>PortConfigSet</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Port: EcucModuleDef</code>:</strong></li>\n<li>Metaklasse zur Repräsentation der Moduldefinition des MCAL-Port-Treibers im BSW-Modul-Metamodell.</li>\n<li><em>Multiplizität:</em> <code>0..1</code> (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Ein System kann den Port-Treiber enthalten oder weglassen, pro ECU-Konfiguration existiert maximal eine Instanz.</li>\n<li><strong><code>PortGeneral: EcucParamConfContainerDef</code>:</strong></li>\n<li>Container für allgemeine, modulweite Konfigurationsparameter (z. B. Aktivierung des Development Error Detection <code>PortDevErrorDetect</code>, Aktivierung von APIs wie <code>PortSetPinDirectionApi</code>, <code>PortSetPinModeApi</code>, <code>PortVersionInfoApi</code>).</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>) ausgehend von <code>Port</code>.</li>\n<li><em>Multiplizität:</em> Exakt <code>1</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>).</li>\n<li><strong><code>PortConfigSet: EcucParamConfContainerDef</code>:</strong></li>\n<li>Multi-Konfigurations-Container für Hardware-abhängige Pin- und Port-Initialisierungsstrukturen (Sub-Container für Ports, Pins, Richtungen, Multiplexing/Modi, Pull-Up/Down-Widerstände).</li>\n<li><em>Beziehung:</em> Komposition (<code>+container</code>) ausgehend von <code>Port</code>.</li>\n<li><em>Multiplizität:</em> Mindestens <code>1</code> (enthält die Post-Build- bzw. Link-Time-Konfigurationssätze).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm bildet keine Laufzeit- oder Call-Sequenzen ab, sondern die Schema-Hierarchie für den AUTOSAR-Konfigurations- und Codegenerierungs-Workflow.</li>\n<li><strong>Laufzeitbezug zur Initialisierung:</strong></li>\n<li>Die in <code>PortConfigSet</code> definierten Parameter werden vom Codegenerator in typisierte C-Datenstrukturen (<code>Port_ConfigType</code>) übersetzt.</li>\n<li>Diese Datenstruktur wird der Initialisierungsfunktion <code>Port_Init(const Port_ConfigType* ConfigPtr)</code> zur Laufzeit beim System-Startup (üblicherweise via <code>EcuM</code>/<code>BswM</code>) übergeben, um die Pin-Multiplexer und Register vor allen anderen Peripherietreibern (DIO, SPI, CAN, PWM) zu konfigurieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations-Klassen & Bindungszeitpunkte:</strong></li>\n<li><strong><code>PortGeneral</code>:</strong> Enthält rein <code>Pre-Compile</code>-Parameter (statische <code>#define</code>-Schalter im generierten <code>Port_Cfg.h</code>).</li>\n<li><strong><code>PortConfigSet</code>:</strong> Ermöglicht je nach Implementierungs- und Systemanspruch <code>Post-Build-Selectable</code>- oder <code>Post-Build-Loadable</code>-Konfigurationen für unterschiedliche ECU-Varianten bzw. Hardware-Revisionen.</li>\n<li><strong>Einschränkungen für MCAL-/BSW-Entwickler:</strong></li>\n<li>Da <code>PortGeneral</code> zwingend die Kardinalität <code>1..1</code> aufweist, muss jeder Port-Treiber-Stack zwingend die globalen Modulschalter bereitstellen.</li>\n<li>Änderungen an Pins zur Laufzeit (z. B. Richtungswechsel oder Modus-Umschaltung) sind nur dann als API verfügbar (<code>Port_SetPinDirection</code>, <code>Port_SetPinMode</code>), wenn die entsprechenden Flags in <code>PortGeneral</code> auf <code>TRUE</code> stehen und der jeweilige Pin in <code>PortConfigSet</code> dafür freigegeben ist.</li>\n</ul>"}], "trans": [{"from": "FIG-51074f550425904c", "to": "FIG-e885f6bf9b3ebdf9", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>[ECUC_Port_00135]: Spezifikationstabelle für das Modul Port oberhalb des Klassendiagramms hinzugefügt; definiert die Konfigurationsvarianten VARIANT-POST-BUILD und VARIANT-PRE-COMPILE sowie Post-Build Variant Support (true).</li>\n<li>PortConfigSet: Multiplizität 1 und Beschreibung über den Tabellenabschnitt Included Containers definiert.</li>\n<li>PortGeneral: Multiplizität 1 und Beschreibung über den Tabellenabschnitt Included Containers definiert.</li>\n</ul>"}, {"from": "FIG-e885f6bf9b3ebdf9", "to": "FIG-30b742e6a471671b", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>[ECUC_Port_00135]: Spezifikationstabelle des Moduls Port (inklusive Konfigurationsvarianten, Post-Build Variant Support und Container-Auflistung) aus dem Schaubild entfernt.</li>\n<li>PortConfigSet: EcucParamConfContainerDef: Beschriftung im Klassenkasten zweizeilig umgebrochen und Assoziationsrollen-Bezeichner +container auf die Verbindungslinie außerhalb des Kastens verschoben.</li>\n</ul>"}, {"from": "FIG-30b742e6a471671b", "to": "FIG-4ae9b051730aea79", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
